// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(address caller, address target, bytes32 role) public {
        vm.assume(target != address(0));
        vm.assume(caller != address(0));
        vm.assume(!c.hasRole(role, target));
        vm.prank(caller);
        try c.renounceRole(role, target) {
            assertTrue(caller == target);
        } catch {
            assertTrue(caller != target);
        }
    }
}
